# R golden fixtures for Level 1's computation (Phase 2, Step 3).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_l1_fixtures.R
#
# Writes, next to this script: one synthetic data CSV per case group
# (data_*.csv, a two-line '#' header then the CSV), then golden.csv with R's answer for every method and variant.
# Every data file is written, READ BACK with read.csv, and the analysis is run
# on what was read, so R computed on exactly the text gaply_core parses.
# Numbers in golden.csv are R doubles printed with %.17g, which round-trips.
#
# Columns of golden.csv:
#   case      a unique name
#   data      the data file
#   method    the Level 1 method id
#   roles     role=column pairs separated by ';'; OLS predictors by '|'
#   variant   student, welch, paired, oneway, pearson, spearman_t,
#             chi_uncorrected, chi_yates_r, ols_f,
#             ols_coef:<term> with <term> '(intercept)' or a column name
#   r_call    the R call that produced the row (no commas)
#   statistic, df1, df2 (NA when there is none), p, n
#
# Synthetic data only. No manuscript or data of anyone's is read.

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

f17 <- function(x) ifelse(is.na(x), "NA", sprintf("%.17g", x))

rows <- list()
add <- function(case, data, method, roles, variant, r_call, statistic, df1, df2, p, n) {
  rows[[length(rows) + 1]] <<- data.frame(
    case = case, data = data, method = method, roles = roles, variant = variant,
    r_call = r_call, statistic = f17(statistic), df1 = f17(df1), df2 = f17(df2),
    p = f17(p), n = as.character(n), stringsAsFactors = FALSE)
}

# Write `df`, read it back, return what was read. The provenance header is
# prepended AFTER the read, so the lines R analysed are exactly the lines
# below the '#' header that the Rust test parses.
roundtrip <- function(df, name) {
  path <- file.path(here, name)
  write.csv(df, path, row.names = FALSE, quote = FALSE, na = "NA")
  back <- read.csv(path, stringsAsFactors = FALSE)
  body <- readLines(path)
  writeLines(c(
    "# Synthetic data for gaply_core's Level 1 R golden fixtures (Phase 2, Step 3).",
    "# Generated by /usr/local/bin/Rscript make_l1_fixtures.R (do not edit by hand).",
    body), path)
  back
}

# ---- independent t (Student and Welch) and two-group ANOVA ---------------
t_case <- function(case, name, d, alt_group_text = FALSE) {
  d$g <- factor(d$g)
  cc <- d[complete.cases(d$y, d$g), ]
  n <- nrow(cc)
  s <- t.test(y ~ g, data = d, var.equal = TRUE)
  add(paste0(case, "_student"), name, "independent_t", "outcome=y;group=g", "student",
      "t.test(y ~ g; var.equal=TRUE)", s$statistic, s$parameter, NA, s$p.value, n)
  w <- t.test(y ~ g, data = d, var.equal = FALSE)
  add(paste0(case, "_welch"), name, "independent_t", "outcome=y;group=g", "welch",
      "t.test(y ~ g; var.equal=FALSE)", w$statistic, w$parameter, NA, w$p.value, n)
}

anova_case <- function(case, name, d) {
  d$g <- factor(d$g)
  cc <- d[complete.cases(d$y, d$g), ]
  a <- summary(aov(y ~ g, data = d))[[1]]
  add(case, name, "one_way_anova", "outcome=y;group=g", "oneway", "summary(aov(y ~ g))",
      a[["F value"]][1], a[["Df"]][1], a[["Df"]][2], a[["Pr(>F)"]][1], nrow(cc))
}

set.seed(20261014)
# Ties (one decimal), unequal groups 7 and 11, one missing outcome; codes 1/2.
d <- data.frame(y = round(c(rnorm(7, 10, 2), rnorm(11, 11.5, 3)), 1), g = c(rep(1, 7), rep(2, 11)))
d$y[4] <- NA
d$y[9] <- d$y[10]                               # a tie across rows
d <- roundtrip(d, "data_t_ties.csv")
t_case("t_ties", "data_t_ties.csv", d)
anova_case("anova_two_groups", "data_t_ties.csv", d)

# One group of size 2; text labels; the second group lower so t is positive.
d <- data.frame(y = c(14.2, 15.9, round(rnorm(6, 9, 1.5), 2)), g = c("a", "a", rep("b", 6)))
d <- roundtrip(d, "data_t_size2.csv")
t_case("t_size2", "data_t_size2.csv", d)

# Very different variances, so Student and Welch differ a lot.
d <- data.frame(y = round(c(rnorm(12, 50, 1), rnorm(5, 47, 9)), 3), g = c(rep(1, 12), rep(2, 5)))
d <- roundtrip(d, "data_t_unequal_var.csv")
t_case("t_unequal_var", "data_t_unequal_var.csv", d)

# ---- paired t -------------------------------------------------------------
paired_case <- function(case, name, d) {
  cc <- d[complete.cases(d$pre, d$post), ]
  p <- t.test(d$pre, d$post, paired = TRUE)
  add(case, name, "paired_t", "first=pre;second=post", "paired", "t.test(pre; post; paired=TRUE)",
      p$statistic, p$parameter, NA, p$p.value, nrow(cc))
}
pre <- round(rnorm(12, 20, 4), 1)
d <- data.frame(pre = pre, post = round(pre + rnorm(12, 1.5, 2), 1))   # post higher: t negative
d$post[5] <- NA
d <- roundtrip(d, "data_paired.csv")
paired_case("paired_missing", "data_paired.csv", d)
d <- data.frame(pre = c(3, 5, 4, 6, 5, 7), post = c(2, 5, 3, 4, 5, 5))   # ties in the differences
d <- roundtrip(d, "data_paired_small.csv")
paired_case("paired_small_ties", "data_paired_small.csv", d)

# ---- one-way ANOVA ----------------------------------------------------------
d <- data.frame(y = round(c(rnorm(4, 5, 1), rnorm(5, 6, 1), rnorm(9, 7.5, 1.4)), 2), g = c(rep(1, 4), rep(2, 5), rep(3, 9)))
d <- roundtrip(d, "data_anova3.csv")
anova_case("anova_three", "data_anova3.csv", d)
d <- data.frame(y = round(c(rnorm(3, 30, 5), rnorm(8, 33, 5), rnorm(6, 29, 5), rnorm(2, 40, 5)), 0),
                g = c(rep("c1", 3), rep("c2", 8), rep("c3", 6), rep("c4", 2)))
d <- roundtrip(d, "data_anova4.csv")
anova_case("anova_four_ties", "data_anova4.csv", d)

# ---- correlations -----------------------------------------------------------
cor_case <- function(case, name, d) {
  cc <- d[complete.cases(d$x, d$y), ]
  n <- nrow(cc)
  p <- cor.test(d$x, d$y, method = "pearson")
  add(paste0(case, "_pearson"), name, "pearson", "x=x;y=y", "pearson", "cor.test(method='pearson')",
      p$estimate, p$parameter, NA, p$p.value, n)
  s <- suppressWarnings(cor.test(d$x, d$y, method = "spearman", exact = FALSE))
  add(paste0(case, "_spearman"), name, "spearman", "x=x;y=y", "spearman_t", "cor.test(method='spearman'; exact=FALSE)",
      s$estimate, n - 2, NA, s$p.value, n)
}
x <- round(rnorm(25, 0, 1), 1)
d <- data.frame(x = x, y = round(0.6 * x + rnorm(25, 0, 0.8), 1))       # ties in both
d$x[7] <- NA
d <- roundtrip(d, "data_cor_pos.csv")
cor_case("cor_pos", "data_cor_pos.csv", d)
x <- round(rnorm(15, 50, 10), 0)
d <- data.frame(x = x, y = round(100 - 0.8 * x + rnorm(15, 0, 6), 0))   # negative
d <- roundtrip(d, "data_cor_neg.csv")
cor_case("cor_neg", "data_cor_neg.csv", d)
d <- data.frame(x = c(1, 2, 2, 3, 4, 4, 4, 5), y = c(2, 1, 3, 3, 5, 4, 6, 6))  # heavy ties, small n
d <- roundtrip(d, "data_cor_ties_small.csv")
cor_case("cor_ties_small", "data_cor_ties_small.csv", d)

# ---- chi-square ---------------------------------------------------------------
expand <- function(tab, rlev, clev) {
  a <- c(); b <- c()
  for (i in seq_along(rlev)) for (j in seq_along(clev)) {
    a <- c(a, rep(rlev[i], tab[i, j])); b <- c(b, rep(clev[j], tab[i, j]))
  }
  data.frame(a = a, b = b)
}
chi_case <- function(case, name, d) {
  tab <- table(d$a, d$b)
  n <- sum(tab)
  u <- suppressWarnings(chisq.test(tab, correct = FALSE))
  add(paste0(case, "_uncorrected"), name, "chi_square_independence", "row=a;column=b", "chi_uncorrected",
      "chisq.test(correct=FALSE)", u$statistic, u$parameter, NA, u$p.value, n)
  y <- suppressWarnings(chisq.test(tab, correct = TRUE))
  two_by_two <- all(dim(tab) == 2)
  # For anything but 2x2, R ignores `correct`: the row is the uncorrected
  # variant, recorded from the correct=TRUE call to show it is the same.
  add(paste0(case, "_correct_true"), name, "chi_square_independence", "row=a;column=b",
      if (two_by_two) "chi_yates_r" else "chi_uncorrected",
      "chisq.test(correct=TRUE)", y$statistic, y$parameter, NA, y$p.value, n)
}
d <- roundtrip(expand(matrix(c(12, 7, 5, 15), 2), c("no", "yes"), c("f", "m")), "data_chi_2x2.csv")
chi_case("chi_2x2", "data_chi_2x2.csv", d)
# |O - E| = 0.238 < 0.5 in every cell: R's correction gives 0.
d <- roundtrip(expand(matrix(c(5, 5, 5, 6), 2), c("no", "yes"), c("f", "m")), "data_chi_2x2_small_diff.csv")
chi_case("chi_2x2_small_diff", "data_chi_2x2_small_diff.csv", d)
d <- roundtrip(expand(matrix(c(10, 3, 7, 4, 12, 6, 6, 5, 14), 3), c("r1", "r2", "r3"), c("k1", "k2", "k3")), "data_chi_3x3.csv")
chi_case("chi_3x3", "data_chi_3x3.csv", d)

# ---- OLS ----------------------------------------------------------------------
ols_case <- function(case, name, d, predictors) {
  f <- as.formula(paste("y ~", paste(predictors, collapse = " + ")))
  fit <- lm(f, data = d)
  s <- summary(fit)
  n <- nobs(fit)
  roles <- paste0("outcome=y;predictors=", paste(predictors, collapse = "|"))
  fs <- s$fstatistic
  add(paste0(case, "_f"), name, "ols", roles, "ols_f", "summary(lm())$fstatistic",
      fs[["value"]], fs[["numdf"]], fs[["dendf"]], pf(fs[["value"]], fs[["numdf"]], fs[["dendf"]], lower.tail = FALSE), n)
  co <- s$coefficients
  for (term in rownames(co)) {
    add(paste0(case, "_coef_", term), name, "ols", roles, paste0("ols_coef:", term), "summary(lm())$coefficients",
        co[term, "t value"], fit$df.residual, NA, co[term, "Pr(>|t|)"], n)
  }
}
d <- data.frame(x1 = round(rnorm(20, 0, 1), 2), x2 = round(rnorm(20, 5, 2), 2), x3 = round(runif(20, 0, 10), 2))
d$y <- round(1 + 0.5 * d$x1 - 0.3 * d$x2 + 0.05 * d$x3 + rnorm(20, 0, 1), 2)
d$x2[11] <- NA
d <- roundtrip(d, "data_ols3.csv")
ols_case("ols_three", "data_ols3.csv", d, c("x1", "x2", "x3"))
d <- data.frame(x1 = 1:10)
d$y <- round(20 - 1.3 * d$x1 + rnorm(10, 0, 1.5), 1)
d <- roundtrip(d, "data_ols1.csv")
ols_case("ols_one_negative", "data_ols1.csv", d, c("x1"))
# Correlated predictors (r = .826 in the data as written).
x1 <- round(rnorm(30, 100, 15), 1)
d <- data.frame(x1 = x1, x2 = round(x1 + rnorm(30, 0, 7), 1))
d$y <- round(3 + 0.02 * d$x1 + 0.04 * d$x2 + rnorm(30, 0, 1), 2)
d <- roundtrip(d, "data_ols_collinearish.csv")
ols_case("ols_correlated", "data_ols_collinearish.csv", d, c("x1", "x2"))
# Predictors on very different scales: around 1e6 and around 1e-2.
d <- data.frame(x1 = round(rnorm(25, 1e6, 3e4), 0), x2 = round(rnorm(25, 0.01, 0.003), 5))
d$y <- round(2 + 3e-5 * d$x1 + 150 * d$x2 + rnorm(25, 0, 1), 3)
d <- roundtrip(d, "data_ols_scales.csv")
ols_case("ols_scales", "data_ols_scales.csv", d, c("x1", "x2"))
# Predictors correlated at about .999.
x1 <- round(rnorm(30, 50, 10), 2)
d <- data.frame(x1 = x1, x2 = round(x1 + rnorm(30, 0, 0.45), 2))
d$y <- round(4 + 0.3 * d$x1 + 0.2 * d$x2 + rnorm(30, 0, 2), 2)
d <- roundtrip(d, "data_ols_r999.csv")
ols_case("ols_r999", "data_ols_r999.csv", d, c("x1", "x2"))

# ---- golden.csv -----------------------------------------------------------------
out <- do.call(rbind, rows)
path <- file.path(here, "golden.csv")
con <- file(path, "w")
writeLines(c(
  "# R golden values for gaply_core's Level 1 computation (Phase 2, Step 3).",
  "# Generated by /usr/local/bin/Rscript make_l1_fixtures.R (do not edit by hand).",
  paste0("# ", R.version.string),
  "# t, r, rho two-sided; F and chi-square upper tail. Numbers are %.17g."
), con)
write.table(out, con, sep = ",", row.names = FALSE, quote = FALSE)
close(con)
cat("wrote", nrow(out), "rows to golden.csv\n")
